DROP TABLE IF EXISTS database_kepemilikian_produksi;
CREATE TABLE database_kepemilikian_produksi (
id INT PRIMARY KEY,
country VARCHAR(100) NOT NULL,
country_slug VARCHAR(100) NOT NULL UNIQUE,
kelistrikan INT NOT NULL DEFAULT 0 CHECK (kelistrikan IN (0, 25, 50, 75, 100)),
mineral_energi INT NOT NULL DEFAULT 0 CHECK (mineral_energi IN (0, 25, 50, 75, 100)),
manufaktur INT NOT NULL DEFAULT 0 CHECK (manufaktur IN (0, 25, 50, 75, 100)),
peternakan INT NOT NULL DEFAULT 0 CHECK (peternakan IN (0, 25, 50, 75, 100)),
agrikultur INT NOT NULL DEFAULT 0 CHECK (agrikultur IN (0, 25, 50, 75, 100)),
perikanan INT NOT NULL DEFAULT 0 CHECK (perikanan IN (0, 25, 50, 75, 100)),
olahan_pangan INT NOT NULL DEFAULT 0 CHECK (olahan_pangan IN (0, 25, 50, 75, 100))
);

