-- SECTION: json/database_SDA\database_sda.pg.sql
DROP TABLE IF EXISTS database_sda;
CREATE TABLE database_sda (
id INT PRIMARY KEY,
country VARCHAR(100) NOT NULL,
country_slug VARCHAR(100) NOT NULL,
emas BOOLEAN NOT NULL DEFAULT FALSE,
uranium BOOLEAN NOT NULL DEFAULT FALSE,
batu_bara BOOLEAN NOT NULL DEFAULT FALSE,
minyak_bumi BOOLEAN NOT NULL DEFAULT FALSE,
gas_alam BOOLEAN NOT NULL DEFAULT FALSE,
garam BOOLEAN NOT NULL DEFAULT FALSE,
litium BOOLEAN NOT NULL DEFAULT FALSE,
logam_tanah_jarang BOOLEAN NOT NULL DEFAULT FALSE,
bijih_besi BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS idx_database_sda_country_lower
ON database_sda (LOWER(country));
CREATE INDEX IF NOT EXISTS idx_database_sda_country_slug_lower
ON database_sda (LOWER(country_slug));
CREATE INDEX IF NOT EXISTS idx_database_sda_country_slug_normalized
ON database_sda (REPLACE(LOWER(country_slug), '_', ' '));
