pertahanan_udara_mobile INT NOT NULL DEFAULT 0,
pesawat_angkut INT NOT NULL DEFAULT 0,
pesawat_pengebom INT NOT NULL DEFAULT 0,
pesawat_pengintai INT NOT NULL DEFAULT 0,
sistem_peluncur_roket INT NOT NULL DEFAULT 0,
tank_tempur_utama INT NOT NULL DEFAULT 0
);
