DROP TABLE IF EXISTS database_icbm_negara;
CREATE TABLE database_icbm_negara (
id SERIAL NOT NULL PRIMARY KEY,
country_id INT NOT NULL,
country_slug VARCHAR(100) NOT NULL UNIQUE,
country_name VARCHAR(100) NOT NULL,
iso VARCHAR(10) NOT NULL,
icbm_status BOOLEAN NOT NULL DEFAULT false,
icbm_jumlah INT NOT NULL DEFAULT 0
);
-- country_id mengacu ke tabel database_alokasi_subsidi (1-212)
-- icbm_status : true jika negara memiliki ICBM terkonfirmasi
