DROP TABLE IF EXISTS database_perjalanan_antar_negara;
CREATE TABLE database_perjalanan_antar_negara (
    country_slug VARCHAR(100) NOT NULL,
    target_country_slug VARCHAR(100) NOT NULL,
    konsumsi_minyak INTEGER NOT NULL CHECK (konsumsi_minyak BETWEEN 2500 AND 10000),
    duration_days SMALLINT NOT NULL CHECK (duration_days BETWEEN 1 AND 60),
    PRIMARY KEY (country_slug, target_country_slug),
    CHECK (country_slug <> target_country_slug)
);

